+// changedStreamPIDs は、previous と current の一方にだけ載っている ES の PID を、昇順に返す。previous が nil なら空を返す。
+func changedStreamPIDs(previous, current *Program) []uint16 {
+	if previous == nil {
+		return []uint16{}
+	}
+	pids := map[uint16]int{}
+	for _, s := range previous.Streams {
