+// TestAnalyzerContinuityAcrossPMTChanges は、PMT から外れた ES が戻ったとき、continuity_counter を数え直すことを確かめる。
+// 放送局は、番組の境目で解説放送の音声などを PMT から外し、戻すときに continuity_counter を 0 から始め直す。
+// discontinuity_indicator は立たないが、パケットは欠けていないので、ドロップと数えない。
+func TestAnalyzerContinuityAcrossPMTChanges(t *testing.T) {
+	t.Parallel()
+
+	video := esEntry{streamType: 0x02, pid: 0x0100}
+	audio := esEntry{streamType: 0x0F, pid: 0x0110}
+	second := esEntry{streamType: 0x0F, pid: 0x0111}
+	caption := esEntry{streamType: 0x06, pid: 0x0130}
+	pat := map[uint16]uint16{programNum: pmtPID}
+
+	tests := []struct {
+		name string
+		// build は、PAT と最初の PMT (video、audio、second) の後に続くパケットを作る。
+		build      func(pmtCC *byte) [][]byte
+		wantSecond int64
+		wantAudio  int64
+	}{
+		{
+			name: "an ES re-added to the PMT restarts its counter",
+			build: func(pmtCC *byte) [][]byte {
+				pkts := [][]byte{esPacket(second.pid, 13, false, true), esPacket(second.pid, 14, false, true)}
+				pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(1, video, audio))...)
+				pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(2, video, audio, second))...)
+
+				return append(pkts, esPacket(second.pid, 0, false, true), esPacket(second.pid, 1, false, true))
+			},
+			wantSecond: 0,
+		},
+		{
+			// PMT に戻る前に ES のパケットが届いても、外れた時点で数え直しているので、ドロップと数えない。
+			name: "an ES resuming before the PMT re-adds it restarts its counter",
+			build: func(pmtCC *byte) [][]byte {
+				pkts := [][]byte{esPacket(second.pid, 14, false, true)}
+				pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(1, video, audio))...)
+				pkts = append(pkts, esPacket(second.pid, 0, false, true))
+				pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(2, video, audio, second))...)
+
+				return append(pkts, esPacket(second.pid, 1, false, true))
+			},
+			wantSecond: 0,
+		},
+		{
+			name: "an ES gap after the re-added PMT is still a drop",
+			build: func(pmtCC *byte) [][]byte {
+				pkts := psiPackets(pmtPID, pmtCC, pmtSection(1, video, audio))
+				pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(2, video, audio, second))...)
+
+				return append(pkts, esPacket(second.pid, 0, false, true), esPacket(second.pid, 5, false, true))
+			},
+			wantSecond: 1,
+		},
+		{
+			// 構成が変わっても、PMT に載り続けた ES は数え直さない。
+			name: "an ES kept in an updated PMT keeps its counter",
+			build: func(pmtCC *byte) [][]byte {
+				pkts := [][]byte{esPacket(audio.pid, 3, false, true)}
+				pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(1, video, audio, second, caption))...)
+
+				return append(pkts, esPacket(audio.pid, 9, false, true))
+			},
+			wantAudio: 1,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			t.Parallel()
+
+			patCC, pmtCC := new(byte), new(byte)
+			pkts := psiPackets(0, patCC, patSection(0, pat))
+			pkts = append(pkts, psiPackets(pmtPID, pmtCC, pmtSection(0, video, audio, second))...)
+			pkts = append(pkts, tt.build(pmtCC)...)
+
+			analyzer := ts.NewAnalyzer(nil)
+			_, err := analyzer.Write(join(pkts))
+			require.NoError(t, err)
+
+			stats := analyzer.Stats()
+			assert.Equal(t, tt.wantSecond, statsOf(stats, second.pid).Drops, "second audio drops")
+			assert.Equal(t, tt.wantAudio, statsOf(stats, audio.pid).Drops, "audio drops")
+		})
+	}
+}
diff --git a/docs/spec.v1.md b/docs/spec.v1.md
index 04ba7dd0..1877835f 100644
--- a/docs/spec.v1.md
+++ b/docs/spec.v1.md
@@ -1044,6 +1044,7 @@ mikanは、ストリームを開くたびに、そのストリームを受信し
 mikanは、書き込むTSを188バイトのパケット単位で流し読みし、次の処理をその場で行います。

 - PIDごとに、ドロップ（continuity counterの不連続）、エラー（transport_error_indicator）、スクランブル（transport_scrambling_control）の数を数えます。
+  - PMTの更新でESが外れたときと加わったときは、そのPIDのcontinuity counterを数え直します。放送局は、番組の境目で解説放送の音声などをPMTから外し、戻すときにcontinuity counterを0から始め直します。discontinuity_indicatorは立ちませんが、パケットは欠けていないので、ドロップと数えません。
   - 録画には全PIDの合計を記録し、セグメントごとに、PIDごとの内訳も、PMTと決まったPIDから分かる種類（映像、音声、字幕・データ、番組情報、不明）と一緒に記録します。映像のドロップか、データ放送のような見なくてよいPIDのドロップかを見分けるためです。PMTに載っているPIDには、stream_typeと、ストリーム識別記述子のcomponent_tagも記録します（#827）。component_tagは、EPGの映像と音声のコンポーネントと対応づけるのに使います。録画中は、書いているセグメントのバイト数、ドロップ、エラー、スクランブルの数と、直前の間隔のビットレートを、10秒ごとにDBの`recording_live_stats`に書きます（#829）。セグメントを閉じたら、閉じたセグメントの数は録画とファイルに足し、この表は0に戻します。システムの状態の画面と`/metrics`は、閉じたセグメントの数とこの表を足して読みます。30秒より前に書いた様子は、mikanが落ちた後の古い値なので、ビットレートとして出しません。DBに届かずに仮の録画で始めた間は（#1073）、録画の行がないので書きません。見るためだけなので、書けなくても録画は止めません。引き継ぎで2つのmikanが同じ録画を書く間は、後から書いた方が残ります。録画の詳細の品質の欄から、セグメントを足し合わせた表を開けます。表には、stream_typeから決めたコーデックの名前（MPEG-2、H.264、HEVC、AACなど。名前のないものは0x06のように書きます）と、component_tag、パケットの数を録画の長さ（途切れた区間を除きます。終えた日時を記録できずに止まった録画では分からないので、出しません）で割った平均のビットレート、全PIDの合計の行を出します。記録する前に録ったセグメントでは、コーデックとcomponent_tagは出しません。録画しながら数えた内訳は、引き継ぎで重なった区間を二重に数えます。解析し直す（6.1）と、重なった区間を除いた内訳に置き換えます（#473）。
   - スクランブルされたままかを決める（[5.5](#55-録画の状態)、[7.1](#71-再生経路)、#1517）ために、PIDごとに、ペイロードを持ち、transport_error_indicatorの立っていないパケットの数と、そのうちスクランブルされていたものの数も数えます。割合は、PMTに載ったES（映像、音声、字幕・データ）のPIDだけで出します。PAT、PMT、ECM、EITのようなセクションはスクランブルされないので、数に入れると割合が薄まり、復号できているように見えるからです。ペイロードのないパケットはスクランブルの対象にならず、誤りのあるパケットはヘッダーを信用できないので、数えません。この数を記録する前に録ったセグメントでは、パケットの数からエラーの数を引いた数と、スクランブルの数で近い値を出します。
   - 引き継ぎで古いmikanと新しいmikanが同じ時間を重ねて録ったときは、新しいmikanのセグメントが始まった後の分を、古いmikanの集計から差し引きます。重なった区間は新しいmikanでも数えるので、差し引かないと二重に数えます。録画の後に解析し直すとき（6.1）も、つながずに残したセグメントでは、後のセグメントの最初のIフレームのPTSに届いた時点までを、前のセグメントの集計とします（#525）。映像のないサービス（ラジオ）ではPTSで位置を合わせられないので、差し引きません。

